query MexUsyncQuery($include_about_status, $include_country_code, $include_username, $input) {
  jid
  country_code
  __typename
  timestamp
  status
  username_info {
    username
    state
    pin
    text
    xwa2_fetch_wa_users {
      about_status_info {
        xwa2_fetch_wa_users {
          about_status_info {
            id
          }
        }
      }
    }
  }
}
